  "prompt": "prompts/physics_committee_luna_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how quantum information can be protected despite decoherence, making reliable quantum computation physically conceivable. This is a foundational advance in quantum information physics.",
        "attribution": "Shor and Steane independently introduced landmark quantum error-correcting codes, while Kitaev developed influential topological approaches. The selected three capture distinct, central contributions, though the field grew through many further contributions.",
        "maturity": "The theory has been tested through increasingly capable experiments and underpins current efforts toward fault-tolerant devices. Practical large-scale error correction remains incomplete, but the foundational result is mature.",
        "uncertainties": [
          "The breadth of later contributions makes any three-person attribution selective.",
          "The ultimate scale and impact of fault-tolerant quantum computing remain uncertain."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B016",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit quantum electrodynamics established a powerful regime for controlling and measuring light–matter interactions with superconducting circuits, enabling major advances in quantum optics and quantum information.",
        "attribution": "Blais developed the theoretical framework; Schoelkopf and Wallraff were central to realizing and demonstrating the architecture experimentally. The pairing of theory and experiment is compelling, though the wider field has many contributors.",
        "maturity": "The approach has been reproduced and extended across laboratories over two decades. Its role in quantum processors is established, even as device performance continues to improve.",
        "uncertainties": [
          "The boundary between this contribution and the broader development of superconducting quantum circuits is not sharp."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped-ion quantum computation joined precise control of individual atomic systems with a scalable gate-based architecture, creating a durable platform for quantum information experiments.",
        "attribution": "Cirac and Zoller supplied foundational proposals, and Blatt's experiments demonstrated essential operations. This gives a clear theory–experiment narrative, although the platform was built by a broad international community.",
        "maturity": "High-fidelity gates, entanglement, and error-correction experiments have been repeatedly demonstrated. Large-scale fault tolerance is still a goal rather than an achieved capability.",
        "uncertainties": [
          "The lasting role of trapped ions relative to other computing platforms is not yet settled."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattices turned ultracold atoms into controllable systems for exploring quantum many-body physics, including regimes that are difficult to access in materials.",
        "attribution": "Zoller's theory helped establish the quantum-simulation vision, while Bloch and Greiner made decisive experimental demonstrations. The proposed names represent complementary contributions, though not the entire experimental community.",
        "maturity": "The platform has produced robust, influential results over many years and continues to develop. Its value as a simulator is established, while the reach of its claims for quantitatively solving complex materials remains an active question.",
        "uncertainties": [
          "The extent to which simulations yield results unavailable by other methods is still being established."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Artur Ekert",
        "Charles H. Bennett",
        "Gilles Brassard"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum key distribution gave quantum measurement principles a concrete role in secure communication and helped establish quantum information as an experimental field.",
        "attribution": "Bennett and Brassard introduced the influential BB84 protocol; Ekert independently developed an entanglement-based approach connecting the subject to Bell tests. These are foundational contributions, though the credited list also reflects later network demonstrations.",
        "maturity": "The protocols have been extensively tested and deployed in limited settings. Global, scalable quantum networks remain technically and economically challenging.",
        "uncertainties": [
          "The proposed discovery groups foundational protocols with later network achievements, which have different contributors and levels of maturity."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B031",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum spin Hall effect and topological-insulator framework revealed a new class of electronic phases with protected boundary states, reshaping condensed-matter physics.",
        "attribution": "Kane and Mele developed the theoretical framework, and Molenkamp's experiments provided key evidence for the quantum spin Hall state. The division between theory and decisive experiment is strong, while subsequent materials work involved many groups.",
        "maturity": "The conceptual framework is firmly established and has been extended across multiple systems. Practical device applications are less settled and are not needed to support the basic physics case.",
        "uncertainties": [
          "The scope of the awardable contribution could be drawn around the original theory, the first demonstrations, or the broader family of topological phases."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B021",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks enabled unprecedented precision in timekeeping by combining narrow atomic transitions with control of systematic shifts, opening new tests of fundamental physics.",
        "attribution": "Katori and Ye independently developed and advanced leading approaches, with sustained experimental contributions that made the technology credible. The field also depends on broad advances in lasers, frequency combs, and atomic physics.",
        "maturity": "The clocks are highly mature as precision instruments, with reproducible performance across laboratories. Their further scientific reach continues to grow.",
        "uncertainties": [
          "The Nobel case depends on weighing the conceptual advance against the cumulative nature of precision-instrument development."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B011",
      "proposed_laureates": [
        "Charles L. Bennett",
        "David N. Spergel",
        "Lyman A. Page Jr."
      ],
      "assessment": {
        "nobel_worthiness": "WMAP's full-sky microwave-background measurements made precision cosmology possible and sharply constrained the universe's age, composition, and expansion history.",
        "attribution": "Bennett led the mission, while Page and Spergel made major experimental and analytical contributions. The result was produced by a large collaboration, making individual credit difficult to delimit.",
        "maturity": "The measurements have been independently checked and strengthened by later observations. Their central cosmological conclusions are well established.",
        "uncertainties": [
          "The case for a three-person prize must be balanced against the essential work of the full mission and analysis teams."
        ]
      }
    }
  ]
}
